MC6809RegisterBankInfo::MC6809RegisterBankInfo(/* const TargetRegisterInfo &TRI */) {

  // The ACCUM bank's maximum size is 64 (from ACC64 — a dummy non-allocatable
  // class added solely to set the bank width for i64 support).

  // validate RegBank initialization.
  const RegisterBank &RBACCUM = getRegBank(MC6809::ACCUMRegBankID);
  (void)RBACCUM;
  assert(&MC6809::ACCUMRegBank == &RBACCUM && "Incorrect ACCUM RegBank initialization.");

  const RegisterBank &RBINDEX = getRegBank(MC6809::INDEXRegBankID);
  (void)RBINDEX;
  assert(&MC6809::INDEXRegBank == &RBINDEX && "Incorrect INDEX RegBank initialization.");

  const RegisterBank &RBCC = getRegBank(MC6809::FLAGSRegBankID);
  (void)RBCC;
  assert(&MC6809::FLAGSRegBank == &RBCC && "Incorrect FLAGS RegBank initialization.");

}

const RegisterBank &MC6809RegisterBankInfo::getRegBankFromRegClass(const TargetRegisterClass &RC, LLT) const {
  if (MC6809::BIT1RegClass.hasSubClassEq(&RC) ||
      MC6809::ACC8RegClass.hasSubClassEq(&RC) ||
      MC6809::ACC16RegClass.hasSubClassEq(&RC) ||
      MC6809::ACC32RegClass.hasSubClassEq(&RC) ||
      // Classes that may not be subclasses of ACC8/ACC16 due to spill
      // registers breaking set containment, but still belong to ACCUM bank.
      MC6809::AAcRegClass.hasSubClassEq(&RC) ||
      MC6809::ABcRegClass.hasSubClassEq(&RC) ||
      MC6809::ADcRegClass.hasSubClassEq(&RC) ||
      MC6809::ACC8_ABRegClass.hasSubClassEq(&RC) ||
      MC6809::AALSBcRegClass.hasSubClassEq(&RC) ||
      MC6809::ABLSBcRegClass.hasSubClassEq(&RC)) {
    return getRegBank(MC6809::ACCUMRegBankID);
  } else if (MC6809::INDEX16RegClass.hasSubClassEq(&RC)) {
    return getRegBank(MC6809::INDEXRegBankID);
  } else if (MC6809::CCondRegClass.hasSubClassEq(&RC) ||
             MC6809::AllArithFlagRegClass.hasSubClassEq(&RC) ||
             MC6809::ArithFlagRegClass.hasSubClassEq(&RC) ||
             MC6809::CCFlagRegClass.hasSubClassEq(&RC)) {
    return getRegBank(MC6809::FLAGSRegBankID);
  } else if (MC6809::Imag8RegClass.hasSubClassEq(&RC) ||
             MC6809::Imag16RegClass.hasSubClassEq(&RC) ||
             MC6809::Imag32RegClass.hasSubClassEq(&RC)) {
    return getRegBank(MC6809::ACCUMRegBankID);
  } else if (MC6809::STACK16RegClass.hasSubClassEq(&RC)) {
    return getRegBank(MC6809::INDEXRegBankID);
  }
  llvm_unreachable("Unsupported register kind.");
}

MC6809GenRegisterBankInfo::PartialMappingIdx MC6809GenRegisterBankInfo::getPartialMappingIdx(const LLT &Ty) {
  if (Ty.isVector())
    llvm_unreachable("Vector is unsupported.");
  if (Ty.isPointer())
    return PMI_INDEX;

  switch (Ty.getSizeInBits()) {
  case 1:
    return PMI_COND;
  case 8:
    return PMI_ACC8;
  case 16:
    return PMI_ACC16;
  case 32:
    return PMI_ACC32;
  case 64:
    return PMI_ACC64;
  default:
    llvm_unreachable("Unsupported register size.");
  }
}

void MC6809RegisterBankInfo::getInstrPartialMappingIdxs(const MachineInstr &MI, const MachineRegisterInfo &MRI, SmallVectorImpl<PartialMappingIdx> &OpRegBankIdx) {
  unsigned NumOperands = MI.getNumOperands();
  for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
    auto &MO = MI.getOperand(Idx);
    // Skip operands we cannot meaningfully type-query:
    //   - non-register operands (metadata, immediates, FI, ...)
    //   - register operands naming no register ($noreg, e.g. the
    //     middle slot in DBG_VALUE)
    //   - physical-register operands ($ix, $ab, ...) — MRI.getType()
    //     only returns a meaningful LLT for virtual registers; for
    //     physregs it returns a default-constructed (invalid) LLT,
    //     which would crash getPartialMappingIdx -> getElementCount.
    //
    // Surfaced by picolibc -g builds where DBG_VALUE references the
    // incoming-arg physreg directly, e.g.
    //   DBG_VALUE $ix, $noreg, !"locale", !DIExpression()
    if (!MO.isReg() || !MO.getReg() || MO.getReg().isPhysical())
      OpRegBankIdx[Idx] = PMI_None;
    else
      OpRegBankIdx[Idx] = getPartialMappingIdx(MRI.getType(MO.getReg()));
  }
}

bool MC6809RegisterBankInfo::getInstrValueMapping(const MachineInstr &MI, const SmallVectorImpl<PartialMappingIdx> &OpRegBankIdx, SmallVectorImpl<const ValueMapping *> &OpdsMapping) {
  unsigned NumOperands = MI.getNumOperands();
  for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
    if (!MI.getOperand(Idx).isReg())
      continue;
    // PMI_None marks a register operand we have no bank for (e.g. the
    // empty $noreg slot in DBG_VALUE / DBG_INSTR_REF). Leave its
    // OpdsMapping entry as the default-initialised nullptr; RegBankSelect
    // ignores null entries in operand-mapping arrays.
    if (OpRegBankIdx[Idx] == PMI_None)
      continue;

    auto Mapping = getValueMapping(OpRegBankIdx[Idx], 1);
    if (!Mapping->isValid()) {
      return false;
    }

    OpdsMapping[Idx] = Mapping;
  }
  return true;
}

const RegisterBankInfo::InstructionMapping &MC6809RegisterBankInfo::getSameOperandsMapping(const MachineInstr &MI) const {
  const MachineFunction &MF = *MI.getParent()->getParent();
  const MachineRegisterInfo &MRI = MF.getRegInfo();

  unsigned NumOperands = MI.getNumOperands();
  LLT Ty = MRI.getType(MI.getOperand(0).getReg());

  if (NumOperands != 3 || (Ty != MRI.getType(MI.getOperand(1).getReg())) || (Ty != MRI.getType(MI.getOperand(2).getReg())))
    llvm_unreachable("Unsupported operand mapping.");

  auto Mapping = getValueMapping(getPartialMappingIdx(Ty), 3);
  return getInstructionMapping(DefaultMappingID, 1, Mapping, NumOperands);
}

const RegisterBankInfo::InstructionMapping &MC6809RegisterBankInfo::getInstrMapping(const MachineInstr &MI) const {
  const MachineFunction &MF = *MI.getParent()->getParent();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  unsigned Opc = MI.getOpcode();
  unsigned NumOperands = MI.getNumOperands();

  // Try the default logic for non-generic instructions that are either copies
  // or already have some operands assigned to banks.
  if (!isPreISelGenericOpcode(Opc) || Opc == TargetOpcode::G_PHI) {
    const InstructionMapping &Mapping = getInstrMappingImpl(MI);
    if (Mapping.isValid())
      return Mapping;
  }

  switch (Opc) {
  case TargetOpcode::G_ADD:
  case TargetOpcode::G_SUB: {
    // For i16 add/sub: if an operand is in INDEX bank (X/Y from CC or
    // pointer ops), keep the operation in INDEX and use LEA.
    LLT Ty = MRI.getType(MI.getOperand(0).getReg());
    if (Ty.getSizeInBits() == 16 && !Ty.isPointer()) {
      Register Src1 = MI.getOperand(1).getReg();
      const RegisterBank *RB1 = MRI.getRegBankOrNull(Src1);
      if (RB1 && RB1->getID() == MC6809::INDEXRegBankID) {
        auto Mapping = getValueMapping(PMI_INDEX, 3);
        return getInstructionMapping(DefaultMappingID, 1, Mapping, NumOperands);
      }
    }
    return getSameOperandsMapping(MI);
  }
  // G_ICMP: INDEX-bank CMPX/CMPY would avoid D clobber, but the imported
  // patterns use pointer type (p0) for INDEX16 whereas G_ICMP operands have
  // s16 type, causing pattern mismatch. Fixed at spill expansion level instead.
  case TargetOpcode::G_MUL:
  case TargetOpcode::G_AND:
  case TargetOpcode::G_OR:
  case TargetOpcode::G_XOR:
    return getSameOperandsMapping(MI);
  case TargetOpcode::G_SHL:
  case TargetOpcode::G_LSHR:
  case TargetOpcode::G_ASHR: {
    LLT Ty = MRI.getType(MI.getOperand(0).getReg());
    auto Mapping = getValueMapping(getPartialMappingIdx(Ty), NumOperands);
    return getInstructionMapping(DefaultMappingID, 1, Mapping, NumOperands);
  }
  default:
    break;
  }

  // Track the bank of each register.
  SmallVector<PartialMappingIdx, 4> OpRegBankIdx(NumOperands);
  getInstrPartialMappingIdxs(MI, MRI, OpRegBankIdx);

  // Finally construct the computed mapping.
  SmallVector<const ValueMapping *, 8> OpdsMapping(NumOperands);
  if (!getInstrValueMapping(MI, OpRegBankIdx, OpdsMapping))
    return getInvalidInstructionMapping();

  return getInstructionMapping(DefaultMappingID, /* Cost */ 1, getOperandsMapping(OpdsMapping), NumOperands);
}

void MC6809RegisterBankInfo::applyMappingImpl(MachineIRBuilder &Builder, const OperandsMapper &OpdMapper) const {
  return applyDefaultMapping(OpdMapper);
}
